{"file_path":"/work/tests/test_spec.py","content":"import pytest

from sales_dashboard.loader import (
    daily_conversion_counts,
    dedupe_sessions,
    parse_session_log,
)
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def session(id_, day, converted=True):
    return {"id": id_, "day": day, "converted": converted}


def test_conversion_rate_none_counts_as_not_converted():
    events = [session("a", 1), session("b", 1, None), session("c", 1, False)]
    assert conversion_rate(events) == pytest.approx(1 / 3)
    assert conversion_rate([session("a", 1, None)]) == 0.0


def test_conversion_rate_empty_is_float_zero():
    result = conversion_rate([])
    assert result == 0.0
    assert isinstance(result, float)


def test_pooled_conversion_rate_weights_sessions_not_groups():
    groups = {
        "small": [session("a", 1)],
        "large": [session("b", 1, False), session("c", 2, None), session("d", 3, False)],
        "empty": [],
    }
    assert pooled_conversion_rate(groups) == 0.25


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_pooled_conversion_rate_no_sessions(groups):
    result = pooled_conversion_rate(groups)
    assert result == 0.0
    assert isinstance(result, float)


@pytest.mark.parametrize(
    "counts, days, expected",
    [([1, 2, 4], 0, 0), ([1, 2, 4], 1, 4), ([1, 2, 4], 2, 6),
     ([1, 2, 4], 3, 7), ([1, 2, 4], 10, 7), ([], 0, 0), ([], 2, 0)],
)
def test_conversions_in_window(counts, days, expected):
    assert conversions_in_window(counts, days) == expected


def test_parse_session_log_flags_and_field_whitespace():
    assert parse_session_log([" a , 1 , 1 \n", " b , -2 , 0 ", " c , 3 , \t"]) == [
        session("a", 1, True), session("b", -2, False), session("c", 3, None),
    ]


def test_parse_session_log_skips_blank_and_comment_lines():
    assert parse_session_log([
        "", " \t\n", "# comment", " \t# not,a,session,record", "a,2,1",
    ]) == [session("a", 2)]
    assert parse_session_log([]) == []


@pytest.mark.parametrize("bad_line", ["a,2", "a,2,1,extra", "a,no,1", "a,1.5,0", "a,,1"])
def test_parse_session_log_errors_include_original_line_number(bad_line):
    lines = ["", " # skipped", "ok,1,1", " \t", bad_line]
    with pytest.raises(ValueError, match=r"line 5\b"):
        parse_session_log(iter(lines))


def test_dedupe_sessions_last_duplicate_id_wins_and_result_is_sorted():
    old = session("a", 9)
    replacement = session("a", 2, False)
    events = [old, session("c", 2), session("b", 1), replacement]
    assert dedupe_sessions(events) == [events[2], replacement, events[1]]
    assert events == [old, events[1], events[2], replacement]


def test_dedupe_sessions_empty():
    assert dedupe_sessions([]) == []


def test_daily_conversion_counts_inclusive_zero_filled_and_bounded():
    events = [
        session("outside-before", 0), session("outside-after", 6),
        session("a", 1), session("b", 1), session("c", 3, False),
        session("d", 4, None), session("e", 5),
    ]
    assert daily_conversion_counts(events, 1, 5) == [2, 0, 0, 0, 1]
    assert daily_conversion_counts(events, 1, 1) == [2]
    assert daily_conversion_counts(events, 5, 1) == []
    assert daily_conversion_counts([], 1, 3) == [0, 0, 0]


def test_campaign_summary_pools_rounds_and_counts_nonempty_groups():
    groups = {
        "a": [session("a", 1)],
        "b": [session("b", 3, False), session("c", 5, None)],
        "empty": [],
    }
    assert campaign_summary(groups, 3) == {"rate": 0.333, "recent": 0, "groups": 2}
    assert campaign_summary(groups, 0)["recent"] == 0
    assert campaign_summary(groups, 20)["recent"] == 1


def test_campaign_summary_recent_uses_calendar_days():
    groups = {"a": [session("a", 1), session("b", 4), session("c", 4)]}
    assert campaign_summary(groups, 2) == {"rate": 1.0, "recent": 2, "groups": 1}


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_campaign_summary_no_sessions(groups):
    assert campaign_summary(groups, 10) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_converting_groups_orders_ties_by_name_and_excludes_empty():
    groups = {
        "z": [session("a", 1)],
        "empty": [],
        "b": [session("b", 1, False)],
        "a": [session("c", 1)],
        "middle": [session("d", 1), session("e", 1, None)],
    }
    assert top_converting_groups(groups, 2) == ["a", "z"]
    assert top_converting_groups(groups, 10) == ["a", "z", "middle", "b"]
    assert top_converting_groups(groups, 0) == []
    assert top_converting_groups({"empty": []}, 1) == []
    assert top_converting_groups({}, 1) == []


def test_conversion_rate_by_group_sorted_keys_and_empty_none():
    groups = {
        "z": [],
        "b": [session("b", 1, False)],
        "a": [session("a", 1), session("c", 1, None)],
    }
    result = conversion_rate_by_group(groups)
    assert result == {"a": 0.5, "b": 0.0, "z": None}
    assert list(result) == ["a", "b", "z"]
    assert conversion_rate_by_group({}) == {}


