    "counts, expected",
    [([], 0), ([0, -1, 0], 0), ([1, 2, 3], 3), ([1, 0, 1], 1),
     ([1, 2, -1, 3], 2), ([1, 0, 2, 3, 4, 0, 1], 3)],
)
def test_longest_conversion_streak(counts, expected):
